import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const columns = ["command_id","pgmid","language","sub_category","tech_point_no","source_content","command_code","command_name","location_count","project_id","variable_declaration"];
const norm = (v) => v === null || v === undefined ? "" : String(v).trim();
const lit = (v) => v === null || v === undefined ? "NULL" : typeof v === "number" ? String(v) : `'${String(v).replaceAll("'", "''")}'`;
function psql(sql) { return execFileSync("docker", ["exec","-i","-e","PGPASSWORD=postgres","Xelora-app","psql","-v","ON_ERROR_STOP=1","-At","-h","192.168.8.247","-p","5432","-U","postgres","-d","n8n"], {input: sql, encoding:"utf8", maxBuffer:256*1024*1024}); }
function commandIds() { const out=psql("COPY (SELECT language, command, id FROM analyzes.command_master WHERE language IN ('CL','COBOL')) TO STDOUT WITH (FORMAT csv, DELIMITER E'\\t');\n"); return new Map(out.trimEnd().split("\n").filter(Boolean).map(x=>{const [l,c,id]=x.split("\t");return [`${l}\u0000${c}`,Number(id)]})); }
function sourceRows(db) { const py=String.raw`import json,sqlite3,sys
db=sqlite3.connect(sys.argv[1]); db.row_factory=sqlite3.Row
for r in db.execute('SELECT * FROM "ALL_COBOL_TECHICAL_POINTS_TBL_ADD260909"'):
 d=dict(r); d['language']='COBOL'; print(json.dumps(d,ensure_ascii=False))`; const out=execFileSync("python",["-c",py,db],{encoding:"utf8",maxBuffer:256*1024*1024,env:{...process.env,PYTHONIOENCODING:"utf-8"}}); return out.trimEnd().split("\n").filter(Boolean).map(JSON.parse); }
export function rows(src, ids) { return src.map(s=>{const cmd=norm(s.CMD_NAME); if(cmd==='MOVE'||cmd==='IF') return null; for(const k of ['TP_DTL_NO','SETUMEI','CMD_NAME']) if(!norm(s[k])) throw new Error(`required source field is empty: ${k}`); return {command_id:ids.get(`COBOL\u0000${cmd}`)??null,pgmid:norm(s.PGMID)||null,language:'COBOL',sub_category:norm(s.SETUMEI),tech_point_no:norm(s.TP_DTL_NO),source_content:s.SOURCE_CONTENT==null?null:String(s.SOURCE_CONTENT),command_code:null,command_name:cmd,location_count:1,project_id:1,variable_declaration:norm(s.VAR_DEF_SRC)||null};}).filter(Boolean); }
export function sql(rs, baseline) { const vals=rs.map(r=>`(${columns.map(c=>lit(r[c])).join(', ')})`).join(',\n'); const expected=baseline+rs.length; return `BEGIN;\n\nINSERT INTO analyzes.tech_point (${columns.join(', ')})\nVALUES\n${vals};\n\nDO $$\nBEGIN\n IF (SELECT count(*) FROM analyzes.tech_point WHERE project_id=1 AND language='COBOL' AND command_name='EVALUATE') <> ${expected} THEN RAISE EXCEPTION 'expected ${expected} rows'; END IF;\n IF EXISTS (SELECT 1 FROM analyzes.tech_point WHERE project_id=1 AND language='COBOL' AND command_name='EVALUATE' AND command_code IS NOT NULL) THEN RAISE EXCEPTION 'command_code must remain null'; END IF;\nEND $$;\n\nCOMMIT;\n`; }
function main(){const a=process.argv.slice(2),apply=a.includes('--apply'),db=resolve(a.find(x=>!x.startsWith('--'))||''); if(!db) throw new Error('usage: node append-toin-tech-points-add260909.mjs <sqlite-db> [--apply]'); const rs=rows(sourceRows(db),commandIds()); const baseline=Number(psql("SELECT count(*) FROM analyzes.tech_point WHERE project_id=1 AND language='COBOL' AND command_name='EVALUATE';").trim()); const dir=resolve(dirname(fileURLToPath(import.meta.url)),'backups',`toin-add260909-${new Date().toISOString().replaceAll(/[-:.]/g,'')}`); mkdirSync(dir,{recursive:true}); const before=psql("COPY (SELECT * FROM analyzes.tech_point WHERE project_id=1 AND language='COBOL' AND command_name='EVALUATE' ORDER BY id) TO STDOUT WITH (FORMAT csv, HEADER true);\n"); const q=sql(rs,baseline); writeFileSync(resolve(dir,'before-evaluate.csv'),before); writeFileSync(resolve(dir,'append.sql'),q); const summary={apply,sourceDatabase:db,rows:rs.length,baselineEvaluate:baseline,expectedEvaluate:baseline+rs.length,unmatchedCommands:[...new Set(rs.filter(r=>r.command_id===null).map(r=>r.command_name))],backupDir:dir}; writeFileSync(resolve(dir,'summary.json'),JSON.stringify(summary,null,2)); if(apply) psql(q); console.log(JSON.stringify(summary,null,2));}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)) main();
